/**
 * Inline SVG question figures (problems.figure_svg / figure_alt).
 *
 * The figures are generated by the seed scripts, drawn in currentColor and
 * CSS variables (--fig-accent, --fig-accent-2, --fig-muted, --fig-grid,
 * --fig-fill, defined per theme in app/globals.css) so they follow the light
 * and dark themes. The database has a CHECK constraint with the same rules;
 * this is the second line of defence before the markup reaches
 * dangerouslySetInnerHTML: anything that could run code, load something
 * external or leak styles to the page is refused (the figure is dropped,
 * never "repaired").
 */

export const MAX_FIGURE_BYTES = 61440;

const FORBIDDEN: RegExp[] = [
  /<\s*(script|foreignObject|image|img|iframe|object|embed|style|use|a|link|meta|animate\w*|set)\b/i,
  /\son[a-z]+\s*=/i, // event handlers
  /(?:xlink:)?href\s*=/i, // no links or references of any kind
  /javascript:/i,
  /url\s*\(/i, // no external (or internal) resource references in styles
  /@import/i,
  /<!ENTITY|<!DOCTYPE/i,
];

/** The figure markup if it is safe to inline, otherwise null. */
export function sanitizeFigureSvg(svg: string | null | undefined): string | null {
  if (typeof svg !== 'string') return null;
  const s = svg.trim();
  if (!s.startsWith('<svg ') || !s.endsWith('</svg>')) return null;
  if (new TextEncoder().encode(s).length > MAX_FIGURE_BYTES) return null;
  if (FORBIDDEN.some((re) => re.test(s))) return null;
  // exactly one root <svg> element
  if ((s.match(/<svg[\s>]/g) || []).length !== 1) return null;
  return s;
}

/** A question's figure for the client: both parts, or nothing. */
export function questionFigure(svg: string | null | undefined, alt: string | null | undefined) {
  const clean = sanitizeFigureSvg(svg);
  if (!clean || typeof alt !== 'string' || alt.trim().length < 20) return { figureSvg: null, figureAlt: null };
  return { figureSvg: clean, figureAlt: alt.trim() };
}
